from __future__ import annotations

import importlib.metadata
import json
import shutil
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .ollama_client import OllamaClient


class SelfCheckError(RuntimeError):
    pass


@dataclass(frozen=True)
class Check:
    name: str
    ok: bool
    detail: str


@dataclass(frozen=True)
class SelfCheckResult:
    checks: list[Check]

    @property
    def ok(self) -> bool:
        return all(check.ok for check in self.checks)

    def to_dict(self) -> dict[str, Any]:
        return {
            "ok": self.ok,
            "checks": [
                {"name": check.name, "ok": check.ok, "detail": check.detail}
                for check in self.checks
            ],
        }

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), ensure_ascii=True, sort_keys=True)


def run_self_check(*, client: OllamaClient | None = None) -> SelfCheckResult:
    checks: list[Check] = []

    python_ok = sys.version_info >= (3, 10)
    checks.append(
        Check(
            "python",
            python_ok,
            f"{sys.version_info.major}.{sys.version_info.minor}",
        )
    )

    git_path = shutil.which("git")
    checks.append(Check("git", bool(git_path), git_path or "missing"))

    try:
        version = importlib.metadata.version("doxify")
    except importlib.metadata.PackageNotFoundError:
        version = "not installed"
    checks.append(Check("package", version != "not installed", version))

    try:
        with tempfile.TemporaryDirectory(prefix="doxify-self-check-") as directory:
            probe = Path(directory) / "probe"
            probe.write_text("ok", encoding="utf-8")
            readable = probe.read_text(encoding="utf-8") == "ok"
        checks.append(Check("tempdir", readable, "read/write ok"))
    except OSError as exc:
        checks.append(Check("tempdir", False, str(exc)))

    if client is not None:
        healthy, detail = client.health()
        checks.append(Check("model", healthy, detail))

    return SelfCheckResult(checks=checks)

from __future__ import annotations

import copy
import re
from pathlib import Path
from typing import Any
from urllib.parse import urlsplit

MAX_TEXT_LENGTH = 2048
FILTERED = "[Filtered]"
REDACTED_PATH = "<path>"

SAFE_DATA_COLLECTION: dict[str, Any] = {
    "user_info": False,
    "cookies": {"mode": "off"},
    "http_headers": {"request": {"mode": "off"}},
    "http_bodies": [],
    "url_query_params": {"mode": "off"},
    "graphql": {"document": False, "variables": False},
    "gen_ai": {"inputs": False, "outputs": False},
    "database_query_data": False,
    "queues": False,
    "stack_frame_variables": False,
    "frame_context_lines": 0,
}

SAFE_TAGS = frozenset(
    {
        "command",
        "environment",
        "exit_code",
        "model",
        "outcome",
        "provider",
        "release",
        "status",
    }
)
SAFE_EXTRA_KEYS = frozenset(
    {
        "command",
        "duration_ms",
        "exit_code",
        "model",
        "provider",
        "stage",
        "status",
    }
)
SAFE_LOG_FIELDS = frozenset(
    {
        "command",
        "completion_tokens",
        "duration_ms",
        "ecosystem",
        "event",
        "exit_code",
        "fallback_changes",
        "matches",
        "model",
        "prompt_tokens",
        "provider",
        "replay_score",
        "stage",
        "status",
        "total_tokens",
        "touching",
    }
)
SAFE_SPAN_DATA_KEYS = frozenset(
    {
        "doxify.stage",
        "gen_ai.operation.name",
        "gen_ai.provider.name",
        "gen_ai.request.max_tokens",
        "gen_ai.request.model",
        "gen_ai.request.temperature",
        "gen_ai.response.model",
        "gen_ai.system",
        "gen_ai.usage.input_tokens",
        "gen_ai.usage.output_tokens",
        "gen_ai.usage.total_tokens",
        "http.method",
        "http.status_code",
    }
)

_SENSITIVE_KEY_TERMS = (
    "api_key",
    "apikey",
    "authorization",
    "cookie",
    "credential",
    "github_token",
    "ollama_api_key",
    "password",
    "passwd",
    "private_key",
    "secret",
    "serpapi",
    "session",
    "token",
)
_SECRET_PATTERNS = (
    re.compile(
        r"(?i)((?:api[_-]?key|apikey|access[_-]?token|auth[_-]?token|token|"
        r"secret|password|passwd|authorization)\s*[=:]\s*)([^\s&,'\"]+)"
    ),
    re.compile(r"(?i)\bBearer\s+[A-Za-z0-9._~+/=-]+"),
    re.compile(r"\bgh[pousr]_[A-Za-z0-9]{20,}\b"),
    re.compile(r"\bgithub_pat_[A-Za-z0-9_]{20,}\b"),
    re.compile(r"\bsk-[A-Za-z0-9_-]{16,}\b"),
    re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
)
_ABSOLUTE_PATH_PATTERNS = (
    re.compile(r"(?<![\w.-])/(?:home|Users)/[^\s\"']+"),
    re.compile(r"\b[A-Za-z]:\\Users\\[^\s\"']+"),
)


def _is_sensitive_key(key: str) -> bool:
    lowered = key.casefold()
    return any(term in lowered for term in _SENSITIVE_KEY_TERMS)


def _known_paths(paths: tuple[str | Path, ...]) -> list[str]:
    values: set[str] = set()
    for path in (*paths, Path.cwd()):
        try:
            text = str(Path(path).expanduser())
        except (TypeError, ValueError):
            continue
        if text:
            values.add(text)
    return sorted(values, key=len, reverse=True)


def redact_text(value: Any, *, paths: tuple[str | Path, ...] = ()) -> str:
    text = str(value)
    for pattern in _ABSOLUTE_PATH_PATTERNS:
        text = pattern.sub(REDACTED_PATH, text)
    for path in _known_paths(paths):
        text = text.replace(path, REDACTED_PATH)
    text = _SECRET_PATTERNS[0].sub(r"\1" + FILTERED, text)
    text = _SECRET_PATTERNS[1].sub("Bearer " + FILTERED, text)
    for pattern in _SECRET_PATTERNS[2:]:
        text = pattern.sub(FILTERED, text)
    if len(text) > MAX_TEXT_LENGTH:
        text = text[:MAX_TEXT_LENGTH] + "...[truncated]"
    return text


def redact_value(value: Any, *, depth: int = 0) -> Any:
    if depth > 8:
        return "[Truncated]"
    if isinstance(value, dict):
        return {
            redact_text(key): (
                FILTERED if _is_sensitive_key(str(key)) else redact_value(item, depth=depth + 1)
            )
            for key, item in value.items()
        }
    if isinstance(value, (list, tuple, set)):
        return [redact_value(item, depth=depth + 1) for item in value]
    if isinstance(value, bytes):
        return "[Binary]"
    if isinstance(value, str):
        return redact_text(value)
    return value


def safe_url(value: str) -> str:
    try:
        parsed = urlsplit(value)
    except ValueError:
        return redact_text(value)
    if not parsed.scheme or not parsed.netloc:
        return redact_text(value)
    return f"{parsed.scheme}://{parsed.netloc}{parsed.path}"


def _safe_path(value: Any) -> str:
    text = str(value or "")
    if not text:
        return text
    if text.startswith("/") or re.match(r"^[A-Za-z]:\\", text):
        return REDACTED_PATH
    return Path(text).name or REDACTED_PATH


def _sanitize_extra(extra: Any) -> dict[str, Any]:
    if not isinstance(extra, dict):
        return {}
    safe: dict[str, Any] = {}
    for key, value in extra.items():
        key_text = str(key)
        if key_text in SAFE_EXTRA_KEYS or key_text.startswith("doxify."):
            safe[key_text] = redact_value(value)
    return safe


def _sanitize_tags(tags: Any) -> dict[str, str]:
    if not isinstance(tags, dict):
        return {}
    return {
        str(key): redact_text(value)
        for key, value in tags.items()
        if str(key) in SAFE_TAGS
    }


def _sanitize_frames(exception: dict[str, Any]) -> None:
    stacktrace = exception.get("stacktrace")
    if not isinstance(stacktrace, dict):
        return
    frames = stacktrace.get("frames")
    if not isinstance(frames, list):
        return
    for frame in frames:
        if not isinstance(frame, dict):
            continue
        for key in ("vars", "pre_context", "context_line", "post_context", "abs_path"):
            frame.pop(key, None)
        if "filename" in frame:
            frame["filename"] = _safe_path(frame["filename"])


def sanitize_breadcrumb(crumb: dict[str, Any], _hint: Any = None) -> dict[str, Any] | None:
    if not isinstance(crumb, dict):
        return None
    category = str(crumb.get("category") or "")
    if category not in {"doxify", "doxify.stage", "cli"}:
        return None
    safe = copy.deepcopy(crumb)
    if "message" in safe:
        safe["message"] = redact_text(safe["message"])
    safe["data"] = _sanitize_extra(safe.get("data"))
    return safe


def _sanitize_common(event: dict[str, Any]) -> None:
    event.pop("user", None)
    event.pop("request", None)
    event.pop("modules", None)
    event.pop("device", None)
    event["server_name"] = "doxify-cli"
    event["tags"] = _sanitize_tags(event.get("tags"))
    event["extra"] = _sanitize_extra(event.get("extra"))

    contexts = event.get("contexts")
    if isinstance(contexts, dict):
        event["contexts"] = {
            key: redact_value(value)
            for key, value in contexts.items()
            if key in {"doxify", "runtime", "trace"}
        }

    if "culprit" in event:
        event["culprit"] = redact_text(event["culprit"])
    if "transaction" in event:
        event["transaction"] = redact_text(event["transaction"])

    logentry = event.get("logentry")
    if isinstance(logentry, dict):
        for key in ("message", "formatted"):
            if key in logentry:
                logentry[key] = redact_text(logentry[key])
        params = logentry.get("params")
        if params is not None:
            logentry["params"] = redact_value(params)

    exception = event.get("exception")
    exceptions = exception.get("values", []) if isinstance(exception, dict) else []
    if isinstance(exceptions, list):
        for exception in exceptions:
            if not isinstance(exception, dict):
                continue
            if "value" in exception:
                exception["value"] = redact_text(exception["value"])
            _sanitize_frames(exception)

    breadcrumbs = event.get("breadcrumbs")
    breadcrumbs = breadcrumbs.get("values", []) if isinstance(breadcrumbs, dict) else []
    if isinstance(breadcrumbs, list):
        cleaned = [
            crumb
            for item in breadcrumbs
            if (crumb := sanitize_breadcrumb(item)) is not None
        ]
        event["breadcrumbs"] = {"values": cleaned}


def sanitize_event(event: dict[str, Any], _hint: Any = None) -> dict[str, Any]:
    safe = copy.deepcopy(event)
    _sanitize_common(safe)
    return safe


def sanitize_transaction(event: dict[str, Any], _hint: Any = None) -> dict[str, Any]:
    safe = sanitize_event(event, _hint)
    spans = safe.get("spans")
    if isinstance(spans, list):
        for span in spans:
            if not isinstance(span, dict):
                continue
            if "description" in span:
                span["description"] = redact_text(span["description"])
            span["tags"] = _sanitize_tags(span.get("tags"))
            data = span.get("data")
            if isinstance(data, dict):
                span["data"] = {
                    str(key): redact_value(value)
                    for key, value in data.items()
                    if str(key) in SAFE_SPAN_DATA_KEYS or str(key).startswith("doxify.")
                }

    measurements = safe.get("measurements")
    if isinstance(measurements, dict):
        safe["measurements"] = {
            str(key): value
            for key, value in measurements.items()
            if str(key).startswith("doxify.") and isinstance(value, (int, float))
        }
    return safe


def sanitize_log(log: dict[str, Any], _hint: Any = None) -> dict[str, Any]:
    safe = copy.deepcopy(log)
    if "body" in safe:
        safe["body"] = redact_text(safe["body"])
    attributes = safe.get("attributes")
    if isinstance(attributes, dict):
        safe["attributes"] = {
            str(key): redact_value(value)
            for key, value in attributes.items()
            if str(key) in SAFE_LOG_FIELDS or str(key).startswith("doxify.")
        }
    return safe

from __future__ import annotations

import re
from collections.abc import Iterable
from dataclasses import dataclass, field
from pathlib import Path

from .claims import CITATION_RE, extract_claims
from .errors import SessionError
from .models import Claim, ClaimStatus, CompileSummary, EvidenceCard
from .readme import GENERATED_MARKER
from .verifier import summarize_claims, verify_claims

EVIDENCE_MARKER_RE = re.compile(
    r"<!--\s*doxify-evidence:\s*([^>]*?)\s*-->",
    re.IGNORECASE | re.DOTALL,
)
ATTESTED_MARKER_RE = re.compile(
    r"<!--\s*doxify-attested:\s*([^>]*?)\s*-->",
    re.IGNORECASE | re.DOTALL,
)
COMMENT_RE = re.compile(r"<!--.*?-->", re.DOTALL)
VISIBLE_MARKER_RE = re.compile(r"\[(needs evidence|rejected|GAP)\]", re.IGNORECASE)
SECTION_RE = re.compile(r"^##\s+(.+?)\s*$")
CASE_STUDY_SKIP_TITLES = {"verification summary", "evidence appendix"}


@dataclass
class ArtifactSection:
    title: str
    evidence_ids: list[str] = field(default_factory=list)
    attested: bool = False
    attestation: str | None = None
    claims: list[Claim] = field(default_factory=list)
    visible_markers: list[str] = field(default_factory=list)


@dataclass
class ArtifactReport:
    path: Path
    mode: str
    sections: list[ArtifactSection]
    claims: list[Claim]
    summary: CompileSummary
    unmarked_sections: list[str] = field(default_factory=list)


def parse_fail_on(value: str) -> set[ClaimStatus]:
    if not value or value.strip().lower() in {"", "none"}:
        return set()

    requested = {item.strip().lower() for item in value.split(",") if item.strip()}
    unknown = requested - {status.value for status in ClaimStatus}
    if unknown:
        choices = ", ".join(status.value for status in ClaimStatus)
        raise ValueError(f"Unknown failure status: {', '.join(sorted(unknown))}. Choose from {choices}.")
    return {ClaimStatus(item) for item in requested}


def failing_claims(claims: Iterable[Claim], fail_on: set[ClaimStatus]) -> list[Claim]:
    return [claim for claim in claims if claim.status in fail_on]


def audit_artifact(
    path: Path,
    evidence: list[EvidenceCard],
    *,
    strict: bool = True,
) -> ArtifactReport:
    artifact = path.expanduser().resolve()
    try:
        text = artifact.read_text(encoding="utf-8")
    except OSError as exc:
        raise SessionError(f"Could not read artifact: {artifact}") from exc

    mode = _detect_mode(text)
    sections: list[ArtifactSection] = []
    extracted: list[Claim] = []
    synthetic: list[tuple[str, str, str, ClaimStatus]] = []
    unmarked: list[str] = []

    for title, body in _split_sections(text):
        if mode == "case_study" and title == "preamble":
            continue
        if mode == "case_study" and title.lower() in CASE_STUDY_SKIP_TITLES:
            continue

        evidence_match = EVIDENCE_MARKER_RE.search(body)
        attested_match = ATTESTED_MARKER_RE.search(body)
        evidence_ids = _marker_ids(evidence_match.group(1)) if evidence_match else []
        section_id = _section_id(title)
        visible = [
            match.group(1).lower()
            for match in VISIBLE_MARKER_RE.finditer(_visible_text(body))
        ]
        section = ArtifactSection(
            title=title,
            evidence_ids=evidence_ids,
            attested=bool(attested_match) and not evidence_ids,
            attestation=(
                attested_match.group(1).strip()
                if attested_match is not None
                else None
            ),
            visible_markers=visible,
        )

        if mode == "case_study":
            claims = extract_claims(
                section_id,
                _visible_text(body),
                start_index=len(extracted) + 1,
            )
            section.claims = claims
            extracted.extend(claims)
        elif evidence_ids:
            claims = extract_claims(
                section_id,
                _visible_text(body),
                start_index=len(extracted) + 1,
            )
            for claim in claims:
                if not claim.evidence_ids:
                    claim.evidence_ids = evidence_ids
            section.claims = claims
            extracted.extend(claims)
        elif section.attested:
            reason = section.attestation or "Author-attested section."
            synthetic.append(
                (
                    section_id,
                    f"{title} (author-attested)",
                    f"Author attestation; not verified from repository evidence. {reason}".strip(),
                    ClaimStatus.ATTESTED,
                )
            )
        else:
            unmarked.append(title)
            if strict:
                synthetic.append(
                    (
                        section_id,
                        f"{title} (unmarked)",
                        "Section has no doxify-evidence or doxify-attested marker.",
                        ClaimStatus.NEEDS_EVIDENCE,
                    )
                )

        for marker in visible:
            status = ClaimStatus.REJECTED if marker == "rejected" else ClaimStatus.NEEDS_EVIDENCE
            synthetic.append(
                (
                    section_id,
                    f"{title} contains visible marker [{marker}]",
                    "The artifact still contains an unresolved claim marker.",
                    status,
                )
            )

        sections.append(section)

    verified = verify_claims(extracted, evidence)
    claims = list(verified)
    for section_id, text_value, reason, status in synthetic:
        claims.append(
            Claim(
                id=f"S{len(claims) + 1}",
                text=text_value,
                section_id=section_id,
                status=status,
                reason=reason,
            )
        )

    summary = summarize_claims(
        claims,
        section_count=len(sections),
        evidence_count=len(evidence),
    )
    return ArtifactReport(
        path=artifact,
        mode=mode,
        sections=sections,
        claims=claims,
        summary=summary,
        unmarked_sections=unmarked,
    )


def _detect_mode(text: str) -> str:
    if (
        GENERATED_MARKER in text
        or EVIDENCE_MARKER_RE.search(text)
        or ATTESTED_MARKER_RE.search(text)
    ):
        return "readme"
    if VISIBLE_MARKER_RE.search(text) or CITATION_RE.search(text):
        return "case_study"
    raise SessionError(
        "Artifact has no Doxify evidence markers or citations. "
        "Mark verified sections with <!-- doxify-evidence: E1 E2 --> "
        "or author-owned sections with <!-- doxify-attested: reason -->."
    )


def _split_sections(text: str) -> list[tuple[str, str]]:
    sections: list[tuple[str, str]] = []
    title = "preamble"
    body: list[str] = []
    in_fence = False

    for line in text.splitlines():
        stripped = line.lstrip()
        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_fence = not in_fence
            body.append(line)
            continue
        match = None if in_fence else SECTION_RE.match(line)
        if match is None:
            body.append(line)
            continue
        if body or title != "preamble":
            sections.append((title, "\n".join(body)))
        title = match.group(1).strip()
        body = []

    if body or title != "preamble":
        sections.append((title, "\n".join(body)))
    return sections


def _visible_text(text: str) -> str:
    lines: list[str] = []
    in_fence = False
    for line in text.splitlines():
        stripped = line.lstrip()
        if stripped.startswith("```") or stripped.startswith("~~~"):
            in_fence = not in_fence
            continue
        if not in_fence:
            lines.append(line)
    return COMMENT_RE.sub("", "\n".join(lines))


def _marker_ids(value: str) -> list[str]:
    return list(dict.fromkeys(part for part in re.split(r"[\s,]+", value.strip()) if part))


def _section_id(title: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-") or "preamble"

from __future__ import annotations

import json
import logging
import os
import sys
from datetime import datetime, timezone
from typing import Any

from .redaction import SAFE_LOG_FIELDS, redact_text, redact_value

LOGGER_NAME = "doxify"
_configured = False

logger = logging.getLogger(LOGGER_NAME)


class _RedactingFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:
        record.msg = redact_text(record.msg)
        if record.args:
            record.args = redact_value(record.args)
        fields = getattr(record, "doxify_fields", None)
        if isinstance(fields, dict):
            record.doxify_fields = {
                key: redact_value(value)
                for key, value in fields.items()
                if key in SAFE_LOG_FIELDS
            }
        return True


class JsonFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        payload: dict[str, Any] = {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "level": record.levelname.lower(),
            "event": record.getMessage(),
            "logger": record.name,
        }
        fields = getattr(record, "doxify_fields", None)
        if isinstance(fields, dict):
            payload.update(fields)
        if record.exc_info and record.exc_info[1] is not None:
            payload["exception"] = redact_text(record.exc_info[1])
        return json.dumps(payload, ensure_ascii=True, sort_keys=True)


class HumanFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        message = f"{record.levelname.lower():<8} {record.getMessage()}"
        fields = getattr(record, "doxify_fields", None)
        if isinstance(fields, dict) and fields:
            rendered = " ".join(f"{key}={value}" for key, value in fields.items())
            message = f"{message} {rendered}"
        return message


def configure_logging() -> None:
    global _configured
    if _configured:
        return

    raw_level = os.environ.get("DOXIFY_LOG_LEVEL", "WARNING").upper()
    level = getattr(logging, raw_level, logging.WARNING)
    json_output = os.environ.get("DOXIFY_LOG_FORMAT", "human").lower() == "json"

    handler = logging.StreamHandler(sys.stderr)
    handler.setFormatter(JsonFormatter() if json_output else HumanFormatter())
    handler.addFilter(_RedactingFilter())

    logger.handlers = [handler]
    logger.setLevel(level)
    logger.propagate = False
    _configured = True


def reset_logging() -> None:
    global _configured
    logger.handlers = []
    logger.setLevel(logging.NOTSET)
    logger.propagate = True
    _configured = False


def log_event(level: int, event: str, **fields: Any) -> None:
    safe_fields = {
        key: redact_value(value)
        for key, value in fields.items()
        if key in SAFE_LOG_FIELDS
    }
    logger.log(level, event, extra={"doxify_fields": safe_fields})

    if level >= logging.WARNING:
        from .monitoring import capture_log

        capture_log(logging.getLevelName(level).lower(), event, safe_fields)

from __future__ import annotations

import logging
import os
import time
from typing import Any, Literal

from ollama import Client, RequestError, ResponseError

from .errors import ModelError
from .log import log_event
from .monitoring import model_span, record_model_usage

DEFAULT_HOST = "http://127.0.0.1:11434"
DEFAULT_MODEL = "gemma3:1b"
DEFAULT_CLOUD_HOST = "https://ollama.com"
DEFAULT_CLOUD_MODEL = "gemma4:31b"

Provider = Literal["local", "cloud"]


def _resolve_provider(value: str | None) -> Provider:
    normalized = (value or "local").strip().lower()
    if normalized in {"local", "ollama", "ollama-local"}:
        return "local"
    if normalized in {"cloud", "ollama-cloud"}:
        return "cloud"
    raise ModelError(f"Unknown provider {value!r}. Use 'local' or 'cloud'.")


class OllamaClient:
    def __init__(
        self,
        model: str | None = None,
        host: str | None = None,
        *,
        provider: str | None = None,
        api_key: str | None = None,
    ) -> None:
        resolved_provider = _resolve_provider(
            provider or os.environ.get("DOXIFY_PROVIDER")
        )
        configured_host = (
            host
            or os.environ.get("DOXIFY_OLLAMA_HOST")
            or (DEFAULT_CLOUD_HOST if resolved_provider == "cloud" else DEFAULT_HOST)
        )
        if "://" not in configured_host:
            configured_host = f"http://{configured_host}"
        self.host = configured_host.rstrip("/")
        self.is_cloud = resolved_provider == "cloud" or "ollama.com" in self.host
        self.provider = "cloud" if self.is_cloud else "local"
        self.model = (
            model
            or os.environ.get("DOXIFY_MODEL")
            or (DEFAULT_CLOUD_MODEL if self.is_cloud else DEFAULT_MODEL)
        )
        self.api_key = REDACTED or os.environ.get("OLLAMA_API_KEY")
        headers = (
            {"Authorization": f"Bearer {self.api_key}"}
            if self.api_key
            else None
        )
        self._client = Client(host=self.host, headers=headers)

    @property
    def label(self) -> str:
        return "Ollama Cloud" if self.is_cloud else "Ollama"

    def health(self) -> tuple[bool, str]:
        if self.is_cloud and not self.api_key:
            return False, (
                "Ollama Cloud requires an API key. Create one at "
                "https://ollama.com/settings/keys and run: "
                "export OLLAMA_API_KEY=..."
            )
        try:
            models = self.list_models()
        except ModelError as exc:
            return False, str(exc)
        if self.model in models:
            return True, f"{self.label} is reachable and {self.model} is available."
        if self.is_cloud:
            return False, (
                f"{self.model} is not available on Ollama Cloud. "
                "Choose another model with --model or see "
                "https://ollama.com/library?c=cloud"
            )
        return False, (
            f"Ollama is reachable, but {self.model} is not installed. "
            f"Run: ollama pull {self.model}"
        )

    def list_models(self) -> list[str]:
        try:
            response = self._client.list()
        except ResponseError as exc:
            raise ModelError(self._response_error(exc)) from exc
        except (RequestError, ConnectionError, OSError) as exc:
            raise ModelError(self._connection_error()) from exc
        return [
            item.model
            for item in response.models
            if getattr(item, "model", None)
        ]

    def ensure_ready(self) -> None:
        healthy, detail = self.health()
        if not healthy:
            raise ModelError(detail)

    def chat(
        self,
        messages: list[dict[str, str]],
        *,
        temperature: float = 0.2,
        num_predict: int = 400,
    ) -> str:
        options: dict[str, Any] = {
            "temperature": temperature,
            "top_p": 0.9,
            "num_ctx": 8192 if self.is_cloud else 4096,
            "num_predict": num_predict,
            "repeat_penalty": 1.1,
        }
        payload: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "stream": False,
            "options": options,
        }
        if not self.is_cloud:
            payload["keep_alive"] = "10m"
        started = time.perf_counter()
        try:
            with model_span(
                provider=self.provider,
                model=self.model,
                temperature=temperature,
                max_tokens=num_predict,
            ) as span:
                response = self._client.chat(**payload)
                duration_ms = (time.perf_counter() - started) * 1000
                prompt_tokens = getattr(response, "prompt_eval_count", None)
                completion_tokens = getattr(response, "eval_count", None)
                total_tokens = (
                    (prompt_tokens or 0) + (completion_tokens or 0)
                    if prompt_tokens is not None or completion_tokens is not None
                    else None
                )
                record_model_usage(
                    span,
                    prompt_tokens=prompt_tokens,
                    completion_tokens=completion_tokens,
                    total_tokens=total_tokens,
                    duration_ms=duration_ms,
                )
        except ResponseError as exc:
            log_event(
                logging.WARNING,
                "model.error",
                provider=self.provider,
                model=self.model,
                status="response_error",
            )
            raise ModelError(self._response_error(exc)) from exc
        except (RequestError, ConnectionError, OSError) as exc:
            log_event(
                logging.WARNING,
                "model.error",
                provider=self.provider,
                model=self.model,
                status="connection_error",
            )
            raise ModelError(self._connection_error()) from exc

        content = response.message.content
        if not content or not content.strip():
            raise ModelError(f"{self.label} returned an empty response.")
        log_event(
            logging.INFO,
            "model.response",
            provider=self.provider,
            model=self.model,
            duration_ms=round(duration_ms, 1),
            prompt_tokens=prompt_tokens,
            completion_tokens=completion_tokens,
            total_tokens=total_tokens,
        )
        return content.strip()

    def _connection_error(self) -> str:
        if self.is_cloud:
            return (
                f"Could not reach Ollama Cloud at {self.host}. "
                "Check your network connection and OLLAMA_API_KEY."
            )
        return f"Could not connect to Ollama at {self.host}. Run: ollama serve"

    def _response_error(self, exc: ResponseError) -> str:
        if exc.status_code in {401, 403}:
            if self.is_cloud:
                return "Ollama Cloud rejected the API key. Check OLLAMA_API_KEY."
            return f"{self.label} rejected the request: {exc}"
        if exc.status_code == 404:
            return (
                f"Model {self.model} is not available on {self.label}. "
                "Pass a different model with --model."
            )
        if exc.status_code == 429:
            return (
                f"{self.label} rate limit reached. Wait a moment and retry, "
                "or choose a different model."
            )
        if exc.status_code >= 500:
            return f"{self.label} is temporarily unavailable: {exc}"
        return f"{self.label} rejected the request: {exc}"

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath

from git import InvalidGitRepositoryError, NoSuchPathError, Repo

from .errors import RepoError
from .models import CommitInfo, RepoSummary
from .paths import (
    is_deploy,
    is_manifest,
    is_readme,
    is_skippable,
    is_test,
    language_for,
)

TOOL_ROOT = Path(__file__).resolve().parents[2]


@dataclass
class RepoContext:
    repo: Repo
    root: Path
    summary: RepoSummary
    commits: list[CommitInfo]
    tracked_files: list[str]


def open_repo(path: Path, *, allow_tool_root: bool = False) -> Repo:
    try:
        root = path.expanduser().resolve(strict=True)
    except OSError as exc:
        raise RepoError(f"Repository path does not exist: {path}") from exc

    if not root.is_dir():
        raise RepoError(f"Repository path is not a directory: {root}")
    if root == Path(root.anchor):
        raise RepoError("Refusing to scan the filesystem root.")
    if root == Path.home():
        raise RepoError("Refusing to scan the home directory.")
    if root == TOOL_ROOT and not allow_tool_root:
        raise RepoError("Refusing to scan Doxify's own repository.")

    try:
        repo = Repo(str(root), search_parent_directories=False)
    except (InvalidGitRepositoryError, NoSuchPathError) as exc:
        raise RepoError(f"Not a git repository: {root}") from exc

    if repo.bare:
        raise RepoError("Bare repositories are not supported.")
    if not repo.working_tree_dir:
        raise RepoError("Repository has no working tree.")
    return repo


def collect_repo_context(repo: Repo, max_commits: int = 100) -> RepoContext:
    root = Path(repo.working_tree_dir or ".").resolve()
    all_files = _tracked_files(repo)
    tracked_files: list[str] = []
    languages: dict[str, int] = {}
    readme_path: str | None = None
    manifests: list[str] = []
    tests: list[str] = []
    deploys: list[str] = []

    for raw in all_files:
        relative = PurePosixPath(raw)
        if is_skippable(relative):
            continue
        tracked_files.append(raw)
        language = language_for(relative)
        if language:
            languages[language] = languages.get(language, 0) + 1
        if relative.suffix or is_readme(relative):
            if is_readme(relative) and readme_path is None:
                readme_path = raw
            if is_manifest(relative):
                manifests.append(raw)
            if is_test(relative):
                tests.append(raw)
            if is_deploy(relative):
                deploys.append(raw)

    commits = _recent_commits(repo, max_commits)
    head_sha, branch = _head_info(repo)
    commit_count, first_date, last_date = _history_summary(repo, commits)

    summary = RepoSummary(
        path=str(root),
        name=root.name,
        head_sha=head_sha,
        branch=branch,
        commit_count=commit_count,
        first_commit_date=first_date,
        last_commit_date=last_date,
        tracked_file_count=len(all_files),
        languages=dict(sorted(languages.items(), key=lambda item: (-item[1], item[0]))),
        readme_path=readme_path,
        manifests=manifests,
        test_files=tests,
        deploy_files=deploys,
    )
    return RepoContext(
        repo=repo,
        root=root,
        summary=summary,
        commits=commits,
        tracked_files=tracked_files,
    )


def _tracked_files(repo: Repo) -> list[str]:
    try:
        output = repo.git.ls_files()
    except Exception:
        return []
    return [line for line in output.splitlines() if line.strip()]


def _recent_commits(repo: Repo, max_commits: int) -> list[CommitInfo]:
    try:
        iterator = repo.iter_commits(max_count=max(1, max_commits))
    except Exception:
        return []

    commits: list[CommitInfo] = []
    for commit in iterator:
        message = commit.message or ""
        subject = message.strip().splitlines()[0] if message.strip() else "(no message)"
        date = datetime.fromtimestamp(commit.committed_date, tz=timezone.utc).date().isoformat()
        commits.append(CommitInfo(hexsha=commit.hexsha[:12], date=date, subject=subject))
    return commits


def _head_info(repo: Repo) -> tuple[str | None, str | None]:
    try:
        if not repo.head.is_valid():
            return None, None
        head_sha = repo.head.commit.hexsha
    except Exception:
        return None, None

    try:
        branch = repo.active_branch.name
    except Exception:
        branch = None
    return head_sha, branch


def _history_summary(
    repo: Repo, commits: list[CommitInfo]
) -> tuple[int, str | None, str | None]:
    try:
        count = int(repo.git.rev_list("--count", "HEAD"))
    except Exception:
        count = len(commits)

    try:
        root_shas = repo.git.rev_list("--max-parents=0", "HEAD").splitlines()
        root_dates = [
            datetime.fromtimestamp(repo.commit(sha).committed_date, tz=timezone.utc)
            .date()
            .isoformat()
            for sha in root_shas
            if sha.strip()
        ]
        first_date = min(root_dates) if root_dates else ""
        last_date = (
            datetime.fromtimestamp(
                repo.head.commit.committed_date, tz=timezone.utc
            )
            .date()
            .isoformat()
        )
    except Exception:
        dates = sorted(commit.date for commit in commits)
        first_date = dates[0] if dates else ""
        last_date = dates[-1] if dates else ""

    return count, first_date or None, last_date or None

from __future__ import annotations

from pathlib import Path, PurePosixPath

SKIP_DIRS = {
    ".git",
    ".hg",
    ".svn",
    ".venv",
    "venv",
    "env",
    "node_modules",
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    ".next",
    "dist",
    "build",
    "coverage",
    "vendor",
    ".idea",
    ".vscode",
}

SECRET_SUFFIXES = {".pem", ".key", ".p12", ".pfx", ".der"}
SECRET_PARTS = ("secret", "credential", "password", "token", "apikey", "api_key")

LANGUAGE_BY_SUFFIX = {
    ".py": "Python",
    ".js": "JavaScript",
    ".jsx": "JavaScript",
    ".mjs": "JavaScript",
    ".cjs": "JavaScript",
    ".ts": "TypeScript",
    ".tsx": "TypeScript",
    ".go": "Go",
    ".rs": "Rust",
    ".java": "Java",
    ".rb": "Ruby",
    ".php": "PHP",
    ".cs": "C#",
    ".c": "C",
    ".h": "C",
    ".cpp": "C++",
    ".hpp": "C++",
    ".swift": "Swift",
    ".kt": "Kotlin",
    ".sh": "Shell",
    ".sql": "SQL",
    ".md": "Markdown",
    ".toml": "TOML",
    ".json": "JSON",
    ".yaml": "YAML",
    ".yml": "YAML",
}

DEPLOY_NAMES = {
    "Dockerfile",
    "docker-compose.yml",
    "docker-compose.yaml",
    "Procfile",
    "fly.toml",
    "render.yaml",
    "netlify.toml",
    "vercel.json",
}

MANIFEST_NAMES = {
    "pyproject.toml",
    "requirements.txt",
    "setup.py",
    "setup.cfg",
    "package.json",
    "go.mod",
    "Cargo.toml",
    "Gemfile",
    "composer.json",
    "pom.xml",
    "build.gradle",
}


def relative_posix(path: Path, root: Path) -> str:
    return path.relative_to(root).as_posix()


def is_skippable(relative: PurePosixPath) -> bool:
    if any(part in SKIP_DIRS for part in relative.parts):
        return True
    name = relative.name.lower()
    if name.endswith((".min.js", ".min.css", ".map")):
        return True
    return bool("lock" in name and name.endswith((".json", ".lock")))


def is_secret(relative: PurePosixPath) -> bool:
    name = relative.name.lower()
    if name == ".env":
        return True
    if name.startswith(".env.") and name != ".env.example":
        return True
    if relative.suffix.lower() in SECRET_SUFFIXES:
        return True
    return any(part in name for part in SECRET_PARTS)


def is_probably_binary(data: bytes) -> bool:
    return b"\x00" in data[:4096]


def read_text_limited(path: Path, max_bytes: int) -> str | None:
    try:
        data = path.read_bytes()
    except OSError:
        return None
    if len(data) > max_bytes or is_probably_binary(data):
        return None
    return data.decode("utf-8", errors="replace")


def is_readme(relative: PurePosixPath) -> bool:
    return relative.name.lower().startswith("readme")


def is_manifest(relative: PurePosixPath) -> bool:
    return relative.name in MANIFEST_NAMES


def is_deploy(relative: PurePosixPath) -> bool:
    if relative.name in DEPLOY_NAMES:
        return True
    return any(part in {".github", ".gitlab"} for part in relative.parts) and relative.suffix.lower() in {
        ".yml",
        ".yaml",
    }


def is_test(relative: PurePosixPath) -> bool:
    name = relative.name.lower()
    if name.startswith("test_") or name.endswith(
        ("_test.py", ".test.js", ".spec.js", ".test.ts", ".spec.ts", "-test.js", "-test.ts")
    ):
        return True
    if "smoke" in name:
        return True
    return "test" in {part.lower() for part in relative.parts} or "tests" in {
        part.lower() for part in relative.parts
    }


def language_for(relative: PurePosixPath) -> str | None:
    return LANGUAGE_BY_SUFFIX.get(relative.suffix.lower())

from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, TypeVar

from pydantic import BaseModel

from .errors import SessionError
from .models import SessionManifest

T = TypeVar("T", bound=BaseModel)


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def prepare_output_dir(path: Path, *, force: bool = False) -> Path:
    output = path.expanduser().resolve()
    if output.exists() and not output.is_dir():
        raise SessionError(f"Output path is not a directory: {output}")
    if output.exists() and any(output.iterdir()) and not force:
        raise SessionError(
            f"Output directory is not empty: {output}. Pass --force to reuse it."
        )
    output.mkdir(parents=True, exist_ok=True)
    return output


def write_json(path: Path, value: BaseModel | dict[str, Any] | list[Any]) -> None:
    if isinstance(value, BaseModel):
        payload = value.model_dump_json(indent=2)
    else:
        payload = json.dumps(value, indent=2, ensure_ascii=False)
    _atomic_write(path, payload + "\n")


def read_model(path: Path, model_type: type[T]) -> T:
    if not path.exists():
        raise SessionError(f"Missing session artifact: {path}")
    try:
        return model_type.model_validate_json(path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise SessionError(f"Could not read {path.name}: {exc}") from exc


def write_text(path: Path, text: str) -> None:
    _atomic_write(path, text.rstrip() + "\n")


def write_manifest(path: Path, manifest: SessionManifest, artifacts: list[str]) -> None:
    manifest.updated_at = utc_now()
    manifest.artifacts = sorted(set(artifacts))
    write_json(path, manifest)


def _atomic_write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp")
    temporary.write_text(text, encoding="utf-8")
    temporary.replace(path)

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .errors import SessionError
from .models import (
    Claim,
    ClaimStatus,
    CompileResult,
    EvidenceCard,
    EvidenceKind,
    RepoSummary,
)
from .text import compact_whitespace

GENERATED_MARKER = "<!-- doxify-generated -->"
CITATION_RE = re.compile(r"\s*\[E\d+\]")
MARKER_RE = re.compile(
    r"\s*\[(?:GAP|needs evidence|attested|rejected)\]",
    re.IGNORECASE,
)
README_FILENAME = "README.md"


@dataclass
class ReadmeResult:
    path: Path
    session_dir: Path
    content: str
    compile_result: CompileResult
    omitted_claims: list[Claim]
    warnings: list[str]
    backup_path: Path | None = None
    session_cleaned: bool = False


def build_readme(
    result: CompileResult,
    *,
    session_dir: Path | None = None,
) -> str:
    repo = result.manifest.repo
    evidence = [card for card in result.evidence if _usable_card(card) is not None]
    claims = result.claims
    lines: list[str] = [GENERATED_MARKER]
    if session_dir is not None:
        lines.append(f"<!-- doxify-compile-session: {session_dir} -->")
    lines.extend(
        [
            f"<!-- doxify-summary: {_summary_text(result)} -->",
            "",
            f"# {repo.name}",
            "",
        ]
    )

    _overview(lines, repo, evidence)
    _what_it_does(lines, evidence)
    _tech_stack(lines, repo, evidence)
    _project_layout(lines, evidence)
    _getting_started(lines, repo, evidence)
    _testing(lines, repo, evidence)
    _limitations(lines, repo)
    _project_notes(lines, claims)

    omitted = [
        claim
        for claim in claims
        if claim.status not in {ClaimStatus.VERIFIED, ClaimStatus.ATTESTED}
    ]
    if omitted:
        lines.extend(
            [
                (
                    f"<!-- doxify-unresolved: {len(omitted)} claim(s) need evidence; "
                    "see claims.json in the compile session. -->"
                ),
                "",
            ]
        )
    lines.append(
        "<!-- doxify-note: Add a LICENSE file and license section if applicable. -->"
    )
    return "\n".join(lines).rstrip() + "\n"


def resolve_readme_target(
    repo_root: Path,
    output: Path | None,
    *,
    force: bool = False,
) -> Path:
    root = repo_root.expanduser().resolve()
    if output is None:
        target = root / README_FILENAME
    else:
        candidate = output.expanduser()
        if candidate.exists() and candidate.is_dir():
            target = candidate / README_FILENAME
        elif candidate.is_file() or candidate.suffix.lower() in {".md", ".markdown"}:
            target = candidate
        else:
            target = candidate / README_FILENAME
        target = target.resolve()

    if target.exists() and target.is_dir():
        raise SessionError(f"README target is a directory: {target}")
    if target.exists() and not force:
        raise SessionError(
            f"README target already exists: {target}. "
            "Pass --force to overwrite it, or use --output to write elsewhere."
        )
    return target


def backup_readme(target: Path, session_dir: Path) -> Path:
    backup_dir = session_dir / "backups"
    backup_dir.mkdir(parents=True, exist_ok=True)
    backup = backup_dir / target.name
    backup.write_bytes(target.read_bytes())
    return backup


def citation_free(text: str) -> str:
    cleaned = CITATION_RE.sub("", text)
    cleaned = MARKER_RE.sub("", cleaned)
    return compact_whitespace(cleaned)


def _overview(lines: list[str], repo: RepoSummary, evidence: list[EvidenceCard]) -> None:
    cards = [
        card
        for card in evidence
        if card.kind == EvidenceKind.METRIC
        and card.title in {"Commit timeline", "Repository size and languages"}
    ]
    body = [card.text for card in cards]
    if not body:
        body = [
            f"{repo.name} contains {repo.tracked_file_count} tracked files"
            + _timeline_suffix(repo)
            + "."
        ]
    _section(lines, "Overview", body, cards)


def _what_it_does(lines: list[str], evidence: list[EvidenceCard]) -> None:
    body: list[str] = []
    ids: list[str] = []

    tools = _first_card(evidence, "registered tools")
    if tools is not None:
        names = _meta_list(tools, "tool_names")
        body.append(tools.text)
        if names:
            body.extend(["", *[f"- `{name}`" for name in names]])
        ids.append(tools.id)

    models = _first_card(evidence, "database models")
    if models is not None:
        names = _meta_list(models, "model_names")
        body.extend(["", models.text])
        if names:
            body.extend(["", *[f"- `{name}`" for name in names]])
        ids.append(models.id)

    routes = _first_card(evidence, "HTTP routes")
    if routes is not None:
        body.extend(["", routes.text])
        ids.append(routes.id)

    data = _first_card(evidence, "records in")
    if data is not None:
        body.extend(["", data.text])
        ids.append(data.id)

    if not body:
        return
    _section(lines, "What it does", body, _cards_by_ids(evidence, ids))


def _tech_stack(lines: list[str], repo: RepoSummary, evidence: list[EvidenceCard]) -> None:
    body: list[str] = []
    ids: list[str] = []

    if repo.languages:
        languages = ", ".join(
            f"{name} ({count})" for name, count in list(repo.languages.items())[:8]
        )
        body.append(f"Languages detected: {languages}.")
        language_card = _first_card(evidence, "Repository size and languages")
        if language_card is not None:
            ids.append(language_card.id)

    dependencies = _first_card(evidence, "Declared dependencies")
    if dependencies is not None:
        names = _meta_list(dependencies, "dependencies")
        if names:
            body.extend(
                [
                    "",
                    "Declared runtime dependencies:",
                    *[f"- `{name}`" for name in names],
                ]
            )
        else:
            body.extend(["", dependencies.text])
        ids.append(dependencies.id)

    if repo.manifests:
        body.extend(["", f"Manifests: {', '.join(repo.manifests)}."])

    if not body:
        return
    _section(lines, "Tech stack", body, _cards_by_ids(evidence, ids))


def _project_layout(lines: list[str], evidence: list[EvidenceCard]) -> None:
    layout = _first_card(evidence, "Top-level structure")
    if layout is None:
        return
    top_level = layout.meta.get("top_level")
    if not isinstance(top_level, dict) or not top_level:
        return

    entries = sorted(
        ((str(name), int(count)) for name, count in top_level.items()),
        key=lambda item: (-item[1], item[0]),
    )
    body = [
        "Top-level paths detected in the repository:",
        "",
        "```text",
        *[f"{name}/ ({count} files)" if count > 1 else f"{name} ({count} file)" for name, count in entries],
        "```",
    ]
    _section(lines, "Project layout", body, [layout])


def _getting_started(
    lines: list[str],
    repo: RepoSummary,
    evidence: list[EvidenceCard],
) -> None:
    scripts = _first_card(evidence, "Project scripts")
    if scripts is None:
        _hidden_note(
            lines,
            "No setup scripts were detected. Add install and run instructions manually.",
        )
        return

    names = _meta_list(scripts, "scripts")
    if not names:
        return

    use_npm = any(path.endswith("package.json") for path in repo.manifests)
    body = ["The project defines these scripts:", "", "```bash"]
    if use_npm:
        body.extend(f"npm run {name}" for name in names)
    else:
        body.extend(names)
    body.extend(["```"])
    _section(lines, "Getting started", body, [scripts])
    _hidden_note(
        lines,
        "Add install, environment, and database setup steps where the repository requires them.",
    )


def _testing(lines: list[str], repo: RepoSummary, evidence: list[EvidenceCard]) -> None:
    test_card = _first_card(evidence, "test-related files")
    test_files = _meta_list(test_card, "test_files") if test_card else repo.test_files
    if not test_files:
        return

    body = [
        "Test files detected:",
        *[f"- `{path}`" for path in test_files],
    ]
    scripts = _first_card(evidence, "Project scripts")
    script_names = _meta_list(scripts, "scripts") if scripts else []
    test_scripts = [name for name in script_names if "test" in name.lower() or "smoke" in name.lower()]
    if test_scripts:
        body.extend(
            [
                "",
                "Test-related scripts: "
                + ", ".join(f"`{name}`" for name in test_scripts),
            ]
        )
    ids = [card.id for card in (test_card, scripts) if card is not None]
    _section(lines, "Testing", body, _cards_by_ids(evidence, ids))
    _hidden_note(
        lines,
        "Add the exact test command and current test status after running it.",
    )


def _limitations(lines: list[str], repo: RepoSummary) -> None:
    body: list[str] = []
    if not repo.deploy_files:
        body.append(
            "Doxify did not detect deployment configuration in the tracked files."
        )
    if repo.test_files:
        body.append(
            "Test files are listed above; this README does not claim that the tests pass."
        )
    body.append(
        "Add installation, environment, deployment, and licensing details that are not "
        "visible in the repository."
    )
    _section(lines, "Limitations and next steps", body, [])


def _project_notes(lines: list[str], claims: list[Claim]) -> None:
    attested = [
        claim
        for claim in claims
        if claim.status == ClaimStatus.ATTESTED and citation_free(claim.text)
    ]
    if not attested:
        return
    body = [f"- {citation_free(claim.text)}" for claim in attested]
    lines.extend(["## Project notes", ""])
    lines.extend(body)
    lines.extend(["", f"<!-- doxify-attested: {' '.join(claim.id for claim in attested)} -->", ""])


def _section(
    lines: list[str],
    title: str,
    body: list[str],
    cards: list[EvidenceCard],
) -> None:
    lines.extend([f"## {title}", ""])
    lines.extend(body)
    ids = " ".join(dict.fromkeys(card.id for card in cards))
    if ids:
        lines.extend(["", f"<!-- doxify-evidence: {ids} -->"])
    lines.append("")


def _hidden_note(lines: list[str], text: str) -> None:
    lines.extend([f"<!-- doxify-note: {text} -->", ""])


def _usable_card(card: EvidenceCard) -> EvidenceCard | None:
    title = card.title.lower()
    if title == "no readme" or "no readme file" in card.text.lower():
        return None
    if not card.text.strip():
        return None
    return card


def _first_card(evidence: list[EvidenceCard], title_fragment: str) -> EvidenceCard | None:
    fragment = title_fragment.lower()
    return next((card for card in evidence if fragment in card.title.lower()), None)


def _cards_by_ids(evidence: list[EvidenceCard], ids: list[str]) -> list[EvidenceCard]:
    wanted = set(ids)
    return [card for card in evidence if card.id in wanted]


def _meta_list(card: EvidenceCard | None, key: str) -> list[str]:
    if card is None:
        return []
    value: Any = card.meta.get(key)
    if isinstance(value, list):
        return [str(item) for item in value]
    return []


def _timeline_suffix(repo: RepoSummary) -> str:
    if repo.first_commit_date and repo.last_commit_date:
        return (
            f" across {repo.commit_count} commits between "
            f"{repo.first_commit_date} and {repo.last_commit_date}"
        )
    return f" across {repo.commit_count} commits"


def _summary_text(result: CompileResult) -> str:
    summary = result.summary
    return (
        f"{summary.verified} verified, {summary.attested} attested, "
        f"{summary.needs_evidence} needing evidence, {summary.rejected} rejected"
    )

from __future__ import annotations

import re

from .models import Claim, ClaimStatus, CompileSummary, EvidenceCard
from .text import content_tokens

NUMBER_RE = re.compile(r"(?<![\w.])(\d[\d,]*(?:\.\d+)?)(?![\w])")
CODE_TOKEN_RE = re.compile(r"`([^`]+)`|\b([a-z]+[A-Z][A-Za-z0-9_]*)\b")

FORBIDDEN_PATTERNS: list[tuple[str, re.Pattern[str], str]] = [
    (
        "oauth",
        re.compile(r"\boauth\b", re.IGNORECASE),
        "The cited evidence does not contain an OAuth implementation.",
    ),
    (
        "tests pass",
        re.compile(r"\b(?:all\s+)?tests?\s+(?:pass|passed|passing)\b", re.IGNORECASE),
        "Doxify did not run the project's tests.",
    ),
    (
        "deployment",
        re.compile(
            r"\b(?:deployed|in production|production-ready|live at|shipped to users)\b",
            re.IGNORECASE,
        ),
        "The cited evidence does not prove deployment.",
    ),
    (
        "users",
        re.compile(r"\b(?:thousands|millions|hundreds)\s+of\s+(?:users|customers)\b", re.IGNORECASE),
        "The cited evidence does not include a verifiable user count.",
    ),
    (
        "performance",
        re.compile(
            r"\b(?:reduced|improved|increased)\b.{0,30}\b(?:latency|performance|speed|by\s+\d+)"
            r"|\b(?:performance|latency|throughput|scalab\w*)\b"
            r"|\boptimi[sz]ed?\s+(?:database|query|queries)\b",
            re.IGNORECASE,
        ),
        "The cited evidence does not include a performance measurement.",
    ),
    (
        "schema validation",
        re.compile(r"\bschema\s+validation\b", re.IGNORECASE),
        "The cited evidence does not show schema validation.",
    ),
    (
        "async operations",
        re.compile(r"\basynchronous\s+operations?\b", re.IGNORECASE),
        "The cited evidence does not show asynchronous operations.",
    ),
    (
        "team size",
        re.compile(r"\b(?:led|managed)\s+(?:a\s+)?team\b|\bteam\s+of\s+\w+", re.IGNORECASE),
        "Code and git history cannot prove team size or leadership.",
    ),
    (
        "awards",
        re.compile(r"\b(?:award-winning|won\s+an?\s+award|awarded)\b", re.IGNORECASE),
        "The cited evidence does not include an award.",
    ),
    (
        "first or only",
        re.compile(r"\b(?:first|only)\b.{0,30}\b(?:tool|platform|project|solution)\b", re.IGNORECASE),
        "The cited evidence does not prove a first or only claim.",
    ),
]


def verify_claims(claims: list[Claim], evidence: list[EvidenceCard]) -> list[Claim]:
    evidence_by_id = {card.id: card for card in evidence}
    record_count = _max_meta_int(evidence, "record_count")

    verified: list[Claim] = []
    for claim in claims:
        if claim.status == ClaimStatus.ATTESTED or claim.user_answer:
            claim.status = ClaimStatus.ATTESTED
            claim.reason = "Author attestation; not verified from repository evidence."
            claim.gap_question = None
            verified.append(claim)
            continue
        verified.append(
            _verify_one(
                claim,
                evidence_by_id,
                record_count=record_count,
            )
        )
    return verified


def summarize_claims(
    claims: list[Claim], *, section_count: int = 0, evidence_count: int = 0
) -> CompileSummary:
    summary = CompileSummary(sections=section_count, evidence_cards=evidence_count)
    for claim in claims:
        if claim.status == ClaimStatus.VERIFIED:
            summary.verified += 1
        elif claim.status == ClaimStatus.ATTESTED:
            summary.attested += 1
        elif claim.status == ClaimStatus.REJECTED:
            summary.rejected += 1
        else:
            summary.needs_evidence += 1
    return summary


def attest_claim(claims: list[Claim], claim_id: str, answer: str) -> Claim:
    for claim in claims:
        if claim.id == claim_id:
            claim.user_answer = answer
            claim.status = ClaimStatus.ATTESTED
            claim.reason = "Author attestation; not verified from repository evidence."
            claim.gap_question = None
            return claim
    raise ValueError(f"Unknown claim: {claim_id}")


def _verify_one(
    claim: Claim,
    evidence_by_id: dict[str, EvidenceCard],
    *,
    record_count: int | None,
) -> Claim:
    lower = claim.text.lower()
    if not claim.evidence_ids:
        claim.status = ClaimStatus.NEEDS_EVIDENCE
        claim.reason = "No citation token was found."
        return claim

    cited = [evidence_by_id.get(evidence_id) for evidence_id in claim.evidence_ids]
    unknown = [evidence_id for evidence_id, card in zip(claim.evidence_ids, cited, strict=False) if card is None]
    if unknown:
        claim.status = ClaimStatus.REJECTED
        claim.reason = f"Unknown evidence citation(s): {', '.join(unknown)}."
        return claim

    cards = [card for card in cited if card is not None]
    evidence_text = " ".join(
        f"{card.title} {card.text} {card.quote or ''} {' '.join(map(str, card.meta.values()))}"
        for card in cards
    )
    evidence_lower = evidence_text.lower()

    forbidden = _forbidden_check(lower, evidence_lower)
    if forbidden is not None:
        status, reason = forbidden
        claim.status = status
        claim.reason = reason
        if status == ClaimStatus.NEEDS_EVIDENCE:
            claim.gap_question = _gap_for(claim.text)
        return claim

    numbers = [normalize_number(value) for value in NUMBER_RE.findall(claim.text)]
    evidence_numbers = {
        normalize_number(value) for value in NUMBER_RE.findall(evidence_text)
    }
    for number in numbers:
        if number in evidence_numbers:
            continue
        if (
            record_count is not None
            and number.isdigit()
            and int(number) > record_count
            and any(word in lower for word in ("scholarship", "record", "entry", "entries"))
        ):
            claim.status = ClaimStatus.REJECTED
            claim.reason = (
                f"Numeric contradiction: the repository contains {record_count} "
                f"records, not {number}."
            )
            return claim
        claim.status = ClaimStatus.NEEDS_EVIDENCE
        claim.reason = f"Number {number} is not supported by the cited evidence."
        claim.gap_question = _gap_for(claim.text)
        return claim

    missing_identifier = _missing_identifier(claim.text, evidence_text)
    if missing_identifier:
        claim.status = ClaimStatus.NEEDS_EVIDENCE
        claim.reason = f"Identifier {missing_identifier} is not present in the cited evidence."
        claim.gap_question = _gap_for(claim.text)
        return claim

    claim_tokens = content_tokens(claim.text)
    evidence_tokens = content_tokens(evidence_text)
    overlap = claim_tokens & evidence_tokens
    title_tokens = set()
    for card in cards:
        title_tokens |= content_tokens(card.title)
        for keyword in card.keywords:
            title_tokens |= content_tokens(keyword)
    minimum_overlap = 1 if len(claim_tokens) <= 4 else 2
    if len(overlap) < minimum_overlap and not (overlap & title_tokens):
        claim.status = ClaimStatus.NEEDS_EVIDENCE
        claim.reason = "Citation does not overlap with the claim's key terms."
        claim.gap_question = _gap_for(claim.text)
        return claim

    claim.status = ClaimStatus.VERIFIED
    claim.reason = "Supported by cited repository evidence."
    claim.gap_question = None
    return claim


def _forbidden_check(
    claim_lower: str, evidence_lower: str
) -> tuple[ClaimStatus, str] | None:
    for name, pattern, reason in FORBIDDEN_PATTERNS:
        if not pattern.search(claim_lower):
            continue
        if name == "oauth":
            if "oauth" not in evidence_lower:
                return ClaimStatus.REJECTED, reason
            return ClaimStatus.NEEDS_EVIDENCE, reason
        if name == "tests pass":
            if not re.search(r"\b(?:tests?|suite)\b.{0,40}\b(?:pass|passed|passing)\b", evidence_lower):
                return ClaimStatus.NEEDS_EVIDENCE, reason
            return ClaimStatus.NEEDS_EVIDENCE, reason
        if name == "deployment":
            if not re.search(r"\b(?:deploy|docker|fly|render|vercel|netlify|procfile)\b", evidence_lower):
                return ClaimStatus.NEEDS_EVIDENCE, reason
            return ClaimStatus.NEEDS_EVIDENCE, reason
        return ClaimStatus.NEEDS_EVIDENCE, reason
    return None


def _missing_identifier(claim_text: str, evidence_text: str) -> str | None:
    identifiers: list[str] = []
    for match in CODE_TOKEN_RE.finditer(claim_text):
        value = (match.group(1) or match.group(2) or "").strip()
        if value and value.lower() not in {"e1", "e2", "e3"}:
            identifiers.append(value)
    evidence_lower = evidence_text.lower()
    for identifier in identifiers:
        if identifier.lower() not in evidence_lower:
            return identifier
    return None


def _max_meta_int(evidence: list[EvidenceCard], key: str) -> int | None:
    values: list[int] = []
    for card in evidence:
        value = card.meta.get(key)
        if isinstance(value, int):
            values.append(value)
    return max(values) if values else None


def normalize_number(value: str) -> str:
    return value.replace(",", "")


def _gap_for(text: str) -> str:
    lower = text.lower()
    if any(word in lower for word in ("deploy", "production", "live")):
        return "Was this deployed? Where, and what evidence can you point to?"
    if any(word in lower for word in ("user", "customer", "people")):
        return "Do you have a verifiable user count or outcome for this?"
    if any(word in lower for word in ("test", "passed", "coverage")):
        return "Did you run the tests? What was the result?"
    if any(word in lower for word in ("team", "led", "managed")):
        return "What was your specific role and team context?"
    if any(word in lower for word in ("performance", "latency", "faster", "reduced")):
        return "Do you have a measurement or benchmark that supports this?"
    return f"What evidence supports this sentence: {text[:140]}?"

from __future__ import annotations

import re

from .models import Claim, ClaimStatus
from .text import compact_whitespace

CITATION_RE = re.compile(r"\[(E\d+)\]")
GAP_RE = re.compile(r"\[GAP\]", re.IGNORECASE)
SENTENCE_SPLIT_RE = re.compile(r"(?<=[.!?])((?:\s*\[E\d+\])*)\s+(?=[A-Z0-9\"“']|\[GAP\])")
PREAMBLE_RE = re.compile(
    r"^(?:okay|sure|certainly|of course|here(?:['\u2019]s| is)|based on|the following)\b",
    re.IGNORECASE,
)
HEADING_RE = re.compile(r"^\s*#{1,6}\s+")
BULLET_RE = re.compile(r"^\s*(?:[-*+]|\d+[.)])\s+")


def extract_claims(section_id: str, body: str, *, start_index: int = 1) -> list[Claim]:
    claims: list[Claim] = []
    for paragraph in _paragraphs(body):
        for sentence in _sentences(paragraph):
            text = compact_whitespace(sentence)
            if not text or _is_preamble(text):
                continue
            evidence_ids = list(dict.fromkeys(CITATION_RE.findall(text)))
            is_gap = bool(GAP_RE.search(text))
            clean_text = compact_whitespace(GAP_RE.sub("", text))
            status = ClaimStatus.NEEDS_EVIDENCE
            gap_question = None
            if is_gap or not evidence_ids:
                gap_question = _gap_question(clean_text)

            claims.append(
                Claim(
                    id=f"C{start_index + len(claims)}",
                    text=clean_text,
                    section_id=section_id,
                    evidence_ids=evidence_ids,
                    status=status,
                    gap_question=gap_question,
                )
            )
    return claims


def parse_citations(text: str) -> list[str]:
    return list(dict.fromkeys(CITATION_RE.findall(text)))


def _paragraphs(body: str) -> list[str]:
    paragraphs: list[str] = []
    current: list[str] = []
    for raw_line in body.splitlines():
        line = HEADING_RE.sub("", raw_line)
        line = BULLET_RE.sub("", line).strip()
        if not line:
            if current:
                paragraphs.append(" ".join(current))
                current = []
            continue
        current.append(line)
    if current:
        paragraphs.append(" ".join(current))
    return paragraphs


def _sentences(paragraph: str) -> list[str]:
    chunks = SENTENCE_SPLIT_RE.split(paragraph)
    sentences: list[str] = []
    current = chunks[0] if chunks else ""
    for index in range(1, len(chunks) - 1, 2):
        citations = chunks[index].strip()
        if citations:
            current = f"{current} {citations}"
        if current.strip():
            sentences.append(current.strip())
        current = chunks[index + 1]
    if current.strip():
        sentences.append(current.strip())
    return sentences


def _is_preamble(text: str) -> bool:
    if CITATION_RE.search(text) or GAP_RE.search(text):
        return False
    return bool(PREAMBLE_RE.search(text.lstrip("\"“”'")))


def _gap_question(text: str) -> str:
    lower = text.lower()
    if any(word in lower for word in ("deployed", "production", "live")):
        return "Was this deployed? Where, and what evidence can you point to?"
    if any(word in lower for word in ("user", "customer", "people")):
        return "Do you have a verifiable user count or outcome for this?"
    if any(word in lower for word in ("test", "passed", "coverage")):
        return "Did you run the tests? What was the result?"
    if any(word in lower for word in ("team", "led", "managed")):
        return "What was your specific role and team context?"
    if any(word in lower for word in ("performance", "latency", "faster", "reduced")):
        return "Do you have a measurement or benchmark that supports this?"
    return f"What evidence supports this sentence: {text[:140]}?"

from __future__ import annotations

import re
from dataclasses import dataclass

from .claims import CITATION_RE, GAP_RE
from .errors import GenerationError, ModelError
from .models import EvidenceCard, SectionSpec
from .ollama_client import OllamaClient
from .prompts import repair_messages, section_messages


@dataclass
class GeneratedSection:
    body: str
    fallback_used: bool
    error: str | None = None


def generate_section(
    client: OllamaClient,
    spec: SectionSpec,
    cards: list[EvidenceCard],
    *,
    repo_name: str,
    role: str | None = None,
    draft: str | None = None,
) -> GeneratedSection:
    messages = section_messages(
        spec,
        cards,
        repo_name=repo_name,
        role=role,
        draft=draft,
    )
    try:
        body = _clean(client.chat(messages, num_predict=260))
        if not _valid(body):
            body = _clean(
                client.chat(
                    repair_messages(
                        spec,
                        cards,
                        body,
                        "The output did not include a citation token or a [GAP] marker.",
                    ),
                    num_predict=260,
                )
            )
        if _valid(body):
            return GeneratedSection(body=body, fallback_used=False)
        raise GenerationError("The model returned text without citations.")
    except (ModelError, GenerationError) as exc:
        return GeneratedSection(
            body=template_section(spec, cards),
            fallback_used=True,
            error=str(exc),
        )


def template_section(spec: SectionSpec, cards: list[EvidenceCard]) -> str:
    usable = [card for card in cards if card.text]
    if not usable:
        return (
            f"The repository does not contain enough evidence for this section. "
            f"[GAP] What would you add to the {spec.title.lower()} section?"
        )

    if spec.id == "snapshot":
        return "\n\n".join(f"{card.text} [{card.id}]" for card in usable)

    if spec.id in {"problem", "reflection"}:
        sentences = [f"{card.text} [{card.id}]" for card in usable]
        if spec.id == "problem":
            sentences.append(
                "[GAP] What user problem motivated this project, and what evidence can you add?"
            )
        else:
            sentences.append(
                "[GAP] Which gap matters most, and what would you change before calling this finished?"
            )
        return "\n\n".join(sentences)

    lead = {
        "snapshot": "The repository provides a concrete snapshot of the project.",
        "problem": "The project context is visible in the repository evidence.",
        "approach": "The implementation follows a structure that can be traced through the evidence.",
        "hard_part": "The hardest part is visible in the implementation and its supporting code.",
        "shipped": "The project ships concrete, inspectable functionality.",
    }.get(spec.id, "The repository provides evidence for this section.")

    sentences = [f"{lead} " + " ".join(f"[{card.id}]" for card in usable[:2]) + "."]
    for card in usable[:3]:
        sentences.append(f"{card.text} [{card.id}]")
    return "\n\n".join(sentences)


def _valid(body: str) -> bool:
    return bool(body.strip()) and (
        bool(CITATION_RE.search(body)) or bool(GAP_RE.search(body))
    )


def _clean(body: str) -> str:
    text = body.strip()
    text = re.sub(r"^```(?:markdown|md|text)?\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*```$", "", text)
    text = re.sub(r"^\s*#{1,6}\s+.*\n+", "", text, count=1)
    text = re.sub(
        r"^(?:okay|sure|certainly)[^\n]*?(?:\.|:)\s*",
        "",
        text,
        count=1,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"^(?:here(?:['\u2019]s| is)|the following)[^\n]*\n+",
        "",
        text,
        count=1,
        flags=re.IGNORECASE,
    )
    text = text.strip()
    if len(text) >= 2 and text[0] in "“\"" and text[-1] in "”\"":
        text = text[1:-1].strip()
    text = re.sub(r"\s*\[(?:E\d*)?$", "", text).strip()
    if text and text[-1] not in ".!?]":
        boundary = max(text.rfind(". "), text.rfind("? "), text.rfind("! "))
        if boundary > 0:
            text = text[: boundary + 1].strip()
    return text

from __future__ import annotations

import re

from .errors import ModelError
from .models import CaseStudySection, Claim, ClaimStatus, DefenseQuestion, EvidenceCard
from .ollama_client import OllamaClient
from .prompts import defense_messages

QUESTION_RE = re.compile(r"^Q:\s*(.+)$", re.MULTILINE)
EVIDENCE_RE = re.compile(r"^EVIDENCE:\s*(.+)$", re.MULTILINE)
WHY_RE = re.compile(r"^WHY:\s*(.+)$", re.MULTILINE)
GAP_RE = re.compile(r"^GAP:\s*(.+)$", re.MULTILINE)


def build_defense(
    client: OllamaClient | None,
    sections: list[CaseStudySection],
    claims: list[Claim],
    evidence: list[EvidenceCard],
    *,
    repo_name: str,
    use_model: bool = True,
) -> list[DefenseQuestion]:
    usable = [
        claim
        for claim in claims
        if claim.status in {ClaimStatus.VERIFIED, ClaimStatus.ATTESTED}
    ]
    if not usable:
        return []

    if use_model and client is not None:
        used_ids = {
            evidence_id for claim in usable[:10] for evidence_id in claim.evidence_ids
        }
        defense_evidence = [card for card in evidence if card.id in used_ids][:10]
        try:
            response = client.chat(
                defense_messages(
                    repo_name,
                    [
                        {
                            "id": claim.id,
                            "text": claim.text,
                            "evidence_ids": claim.evidence_ids,
                        }
                        for claim in usable[:10]
                    ],
                    defense_evidence,
                ),
                num_predict=600,
            )
            questions = _parse(response, evidence)
            if questions:
                return questions
        except ModelError:
            pass

    return _fallback(sections, usable)


def _parse(response: str, evidence: list[EvidenceCard]) -> list[DefenseQuestion]:
    valid_ids = {card.id for card in evidence}
    blocks = re.split(r"(?=^Q:\s)", response.strip(), flags=re.MULTILINE)
    questions: list[DefenseQuestion] = []
    for block in blocks:
        question_match = QUESTION_RE.search(block)
        if not question_match:
            continue
        why_match = WHY_RE.search(block)
        evidence_match = EVIDENCE_RE.search(block)
        gap_match = GAP_RE.search(block)

        outline: list[str] = []
        after_why = block
        if why_match:
            after_why = block[why_match.end() :]
        for raw_line in after_why.splitlines():
            line = raw_line.strip()
            if line.startswith(("-", "*")) and not line.lower().startswith(("why:", "evidence:", "gap:")):
                outline.append(line[1:].strip())

        evidence_ids = []
        if evidence_match:
            evidence_ids = [
                value.strip()
                for value in re.findall(r"E\d+", evidence_match.group(1))
                if value.strip() in valid_ids
            ]

        gap = gap_match.group(1).strip() if gap_match else None
        if gap and gap.upper() == "NONE":
            gap = None

        questions.append(
            DefenseQuestion(
                id=f"Q{len(questions) + 1}",
                question=question_match.group(1).strip(),
                why_asked=why_match.group(1).strip() if why_match else "Tests technical understanding.",
                answer_outline=outline[:3],
                evidence_ids=list(dict.fromkeys(evidence_ids)),
                gap=gap,
            )
        )
        if len(questions) >= 6:
            break
    return questions


def _fallback(sections: list[CaseStudySection], claims: list[Claim]) -> list[DefenseQuestion]:
    questions_by_section = {
        "snapshot": (
            "What does this project actually do, and which evidence proves it?",
            "Interviewers want a concrete summary rather than a pitch.",
        ),
        "problem": (
            "Why does this project exist, and what problem does it solve?",
            "Interviewers test whether you understand the motivation.",
        ),
        "approach": (
            "Why did you structure the implementation this way?",
            "Interviewers want to hear the design reasoning behind the code.",
        ),
        "hard_part": (
            "What was the hardest technical problem, and how did you handle it?",
            "Interviewers probe for depth beyond the happy path.",
        ),
        "shipped": (
            "Which features actually shipped, and how can you prove it?",
            "Interviewers distinguish working software from intentions.",
        ),
        "reflection": (
            "What would you change before relying on this in production?",
            "Interviewers test self-awareness and engineering judgment.",
        ),
    }
    claims_by_section: dict[str, list[Claim]] = {}
    for claim in claims:
        claims_by_section.setdefault(claim.section_id, []).append(claim)

    questions: list[DefenseQuestion] = []
    for section in sections:
        section_claims = claims_by_section.get(section.id, [])
        if not section_claims:
            continue
        question, why = questions_by_section.get(
            section.id,
            (
                f"What is the most important decision in the {section.title.lower()} section?",
                "Interviewers test whether the author can defend the work.",
            ),
        )
        outline = [claim.text for claim in section_claims[:3]]
        evidence_ids = list(
            dict.fromkeys(
                evidence_id
                for claim in section_claims[:3]
                for evidence_id in claim.evidence_ids
            )
        )
        questions.append(
            DefenseQuestion(
                id=f"Q{len(questions) + 1}",
                question=question,
                why_asked=why,
                answer_outline=outline,
                evidence_ids=evidence_ids,
            )
        )
        if len(questions) >= 6:
            break
    return questions

