mkdir -p /tmp/opencode && uv run python - <<'PY'
import sqlite3, json, re, collections, datetime, os

DB = "/home/ekomjah/.local/share/opencode/opencode.db"
SID = "ses_e9322049bffeG0jrm0aY6Eq1WH"
OUT_CURATED = "/tmp/opencode/doxify-curated-data.json"
OUT_FULL = "/tmp/opencode/doxify-agent-session.json"
REPORT = "/tmp/opencode/redaction-report.txt"

MAX_USER_TEXT = 8000
MAX_ASSISTANT_TEXT = 8000
MAX_TOOL_INPUT = 600
MAX_TOOL_OUTPUT = 900
MAX_TOOL_OUTPUT_IMPORTANT = 1400

con = sqlite3.connect(f"file:{DB}?mode=ro", uri=True)
con.row_factory = sqlite3.Row

counts = collections.Counter()

def redact(s: str) -> str:
    if not s:
        return s
    # Order matters: specific secrets first.
    subs = [
        ("run_code", re.compile(r"2ea5669e79"), "[redacted-run-code]"),
        ("sentry_org", re.compile(r"ekomjah-denis"), "<sentry-org>"),
        ("sentry_dsn", re.compile(r"https://[0-9a-f]{16,}@o\d+\.ingest\.[A-Za-z0-9.-]+/\d+"), "[redacted-sentry-dsn]"),
        ("sentry_private_url", re.compile(r"https://(?!docs\.|www\.)[A-Za-z0-9-]+\.sentry\.io/[^\s)\"']+"), "[redacted-sentry-url]"),
        ("gh_token", re.compile(r"\b(?:ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\b"), "[redacted-token]"),
        ("sk_token", re.compile(r"\bsk-[A-Za-z0-9_-]{16,}\b"), "[redacted-token]"),
        ("dev_token", re.compile(r"\bdev_[A-Za-z0-9]{20,}\b"), "[redacted-token]"),
        ("bearer", re.compile(r"(?i)(\bbearer\s+)[A-Za-z0-9._~+/=-]{12,}"), r"\1[redacted]"),
        ("auth_header", re.compile(r"(?i)(\bauthorization\s*[:=]\s*)(?:bearer\s+)?[A-Za-z0-9._~+/=-]{12,}"), r"\1[redacted]"),
        ("secret_assign", re.compile(r"(?i)\b(api[_-]?key|secret|password|passwd|access[_-]?token|auth[_-]?token|bearer[_-]?token)\b(\s*[:=]\s*[\"']?)([^\s\"',}]{8,})"), r"\1\2[redacted]"),
        ("secret_env", re.compile(r"(?i)\b(SENTRY_DSN|OLLAMA_API_KEY|SERPAPI_API_KEY|GITHUB_TOKEN|OPENAI_API_KEY|ANTHROPIC_API_KEY|DEV_API_KEY|MLH_[A-Z_]+)\b(\s*=\s*[\"']?)([^\s\"']{8,})"), r"\1\2[redacted]"),
        ("file_url", re.compile(r"file:///home/ekomjah"), "file://~"),
        ("home_path", re.compile(r"/home/ekomjah"), "~"),
        ("bare_user", re.compile(r"\bekomjah\b"), "[user]"),
        ("email", re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,6}\b"), "[redacted-email]"),
    ]
    for name, pat, repl in subs:
        s, n = pat.subn(repl, s)
        if n:
            counts[name] += n
    return s

def trunc(s, n):
    s = s or ""
    if len(s) <= n:
        return s
    return s[:n] + f"\n… [truncated {len(s)-n} chars]"

def tool_input_text(tool, inp):
    if isinstance(inp, dict):
        if tool == "bash":
            return str(inp.get("command", ""))
        if tool in ("read", "write", "edit"):
            path = inp.get("filePath") or inp.get("path") or ""
            if tool == "edit":
                return f"file: {path}\nold:\n{trunc(inp.get('oldString',''), 300)}\nnew:\n{trunc(inp.get('newString',''), 600)}"
            if tool == "write":
                return f"file: {path}\ncontent:\n{trunc(inp.get('content',''), 900)}"
            return f"file: {path}"
        if tool == "grep":
            return f"pattern: {inp.get('pattern','')}\npath: {inp.get('path','')}"
        if tool == "webfetch":
            return str(inp.get("url", ""))
        if tool == "websearch":
            return str(inp.get("query", ""))
        if tool == "question":
            return trunc(json.dumps(inp, ensure_ascii=False), 1600)
        if tool == "todowrite":
            return trunc(json.dumps(inp, ensure_ascii=False), 900)
        return trunc(json.dumps(inp, ensure_ascii=False), MAX_TOOL_INPUT)
    return trunc(str(inp), MAX_TOOL_INPUT)

def tool_output_text(tool, st):
    out = st.get("output")
    if not out and isinstance(st.get("metadata"), dict):
        out = st["metadata"].get("output")
    out = out or ""
    if tool == "question":
        return trunc(str(out), 2000)
    if tool in ("bash", "webfetch", "websearch"):
        return trunc(str(out), MAX_TOOL_OUTPUT_IMPORTANT)
    return trunc(str(out), MAX_TOOL_OUTPUT)

msgs = con.execute(
    "select id, data, time_created from message where session_id=? order by time_created, id",
    (SID,),
).fetchall()

parts_by_msg = collections.defaultdict(list)
for p in con.execute(
    "select id, message_id, data, time_created from part where session_id=? order by time_created, id",
    (SID,),
):
    parts_by_msg[p["message_id"]].append(p)

normalized = []
skipped = collections.Counter()
for m in msgs:
    md = json.loads(m["data"])
    role = md.get("role")
    if role not in ("user", "assistant"):
        skipped[f"role:{role}"] += 1
        continue
    content = []
    for p in parts_by_msg.get(m["id"], []):
        pd = json.loads(p["data"])
        typ = pd.get("type")
        if typ == "text":
            txt = redact(pd.get("text", ""))
            if txt.strip():
                content.append({"type": "text", "text": trunc(txt, MAX_USER_TEXT if role == "user" else MAX_ASSISTANT_TEXT)})
        elif typ == "tool":
            tool = pd.get("tool") or "tool"
            st = pd.get("state") or {}
            content.append({
                "type": "tool_call",
